-- ================================================================
-- 교적(reg_*) 전체 샘플 데이터 - 이식용 시드
-- 원본: local DB (church_id = 33632) 실제 데이터 덤프
--
-- 【사용법】
--   1) 아래 @church_id 값을 대상 교회 ID 로 변경
--        - dev(행복샘교회 2) : SET @church_id = 19715;  ← 현재 설정값
--        - local 재적용      : SET @church_id = 33632;
--   2) 대상 DB 선택 후 전체 실행
--
-- 【주의】
--   - id 값을 원본 그대로 보존하므로 FK(회원/조직/예배/과정) 정합성 유지됨.
--     => 대상 DB 의 reg_* 테이블에 동일 id 가 이미 있으면 PK 충돌.
--        신규 교회에 최초 1회 적재하는 용도. 재적재 시 아래 CLEAN 블록 사용.
--   - member_no(M-2026xxx)는 전역 UNIQUE. 대상 DB에 같은 member_no 있으면 충돌.
--   - churchero_user_id 는 전부 NULL (교회로 users 연동 없음).
--   - 감사로그(reg_audit_logs)는 제외 (앱 사용 시 자동 재생성).
--   - 데이터 없는 테이블 제외: reg_families, reg_service_teams,
--     reg_service_members, reg_offering_records, reg_messages.
-- ================================================================

-- USE gyohyero_db;            -- ← 대상 DB 명에 맞게 주석 해제/수정

SET @church_id = 19715;       -- ★★★ 대상 교회 ID (19715: 행복샘교회 2 dev / 33632: local 원본) ★★★

SET FOREIGN_KEY_CHECKS = 0;

