-- ================================================================
-- 확인 쿼리
-- ================================================================
SELECT 'reg_members'        AS tbl, COUNT(*) AS cnt FROM reg_members              WHERE church_id=@church_id
UNION ALL SELECT 'reg_organizations',        COUNT(*) FROM reg_organizations       WHERE church_id=@church_id
UNION ALL SELECT 'reg_services',             COUNT(*) FROM reg_services            WHERE church_id=@church_id
UNION ALL SELECT 'reg_attendance_records',   COUNT(*) FROM reg_attendance_records  WHERE church_id=@church_id
UNION ALL SELECT 'reg_visit_records',        COUNT(*) FROM reg_visit_records       WHERE church_id=@church_id
